defmodule Bard.Compiler.CtesTest do
  use ExUnit.Case, async: true

  alias Bard.Compiler.Ctes

  # Expected outputs come from dbt's own `inject_ctes_into_sql`, generated by
  # test/fixtures/ctes/generate_cases.py.
  @cases "test/fixtures/ctes/cases.json" |> File.read!() |> Jason.decode!()

  for {name, %{"sql" => sql, "ctes" => ctes, "expected" => expected}} <- @cases do
    test "matches dbt: #{name}" do
      ctes =
        unquote(ctes) |> Enum.with_index() |> Enum.map(fn {sql, i} -> {"model.p.#{i}", sql} end)

      assert Ctes.inject(unquote(sql), ctes) == unquote(expected)
    end
  end

  test "no CTEs leaves the SQL alone" do
    assert Ctes.inject("select 1", []) == "select 1"
  end

  describe "collect/3" do
    # top refs eph_b and eph_a; eph_b refs eph_a.
    @ephemerals %{
      "model.p.top" => ["model.p.eph_b", "model.p.eph_a"],
      "model.p.eph_b" => ["model.p.eph_a"]
    }
    @info %{
      "model.p.eph_a" => {"eph_a", "select 1"},
      "model.p.eph_b" => {"eph_b", "select * from __dbt__cte__eph_a"}
    }

    test "nested ephemerals come first, each only once" do
      assert [{"model.p.eph_a", a}, {"model.p.eph_b", b}] =
               Ctes.collect("model.p.top", @ephemerals, @info)

      assert a == " __dbt__cte__eph_a as (\nselect 1\n)"
      assert b == " __dbt__cte__eph_b as (\nselect * from __dbt__cte__eph_a\n)"
    end

    test "a node with no ephemeral refs needs no CTEs" do
      assert Ctes.collect("model.p.eph_a", @ephemerals, @info) == []
    end
  end
end
